-- Data/Spots.lua and Data/Trainers.lua (generated by tools/gen_spots.py and tools/gen_npcs.py): the shape the map
-- view relies on, the routes, and three positions known from the game.
local function load(file)
	local ns = {}
	assert(loadfile(file))("SkillupHelper", ns)
	return ns.Data
end

local D = load("Data/Spots.lua").spots
local SKILLS = { 633, 186, 182, 393, 356 }
local OUTDOOR = { 633, 186, 182, 393 }
local LOOP_CAP = 40

local function percent(v)
	return type(v) == "number" and v >= 0 and v <= 100
end

-- every spot of the skills that have spots, with its skill
local function eachSpot(fn)
	for _, id in ipairs(OUTDOOR) do
		for _, spot in ipairs(D.skills[id].spots) do
			fn(spot, D.skills[id], id)
		end
	end
end

-- the loop's length in yards, from the map percents and the map's size in yards
local function legs(spot)
	local map = D.maps[spot.map]
	local n = #spot.pts / 2
	local total = 0
	if n < 2 then
		return 0
	end
	for i = 1, n do
		local j = i % n + 1
		local dx = (spot.pts[2 * i - 1] - spot.pts[2 * j - 1]) / 100 * map.w
		local dy = (spot.pts[2 * i] - spot.pts[2 * j]) / 100 * map.h
		total = total + math.sqrt(dx * dx + dy * dy)
	end
	return total
end

local function find(skill, map, x, y, reach)
	for _, spot in ipairs(D.skills[skill].spots) do
		if
			spot.map == map
			and not spot.instance
			and math.abs(spot.x - x) <= reach
			and math.abs(spot.y - y) <= reach
		then
			return spot
		end
	end
end

describe("Data/Spots.lua", function()
	it("says where it comes from and labels the unconfirmed bands", function()
		assert.equal(1, D.version)
		assert.is_string(D.build)
		assert.truthy(D.classicSource:find("cmangos", 1, true))
		assert.truthy(D.classicSource:find("unconfirmed for Forever", 1, true))
		assert.same({ yellow = 25, green = 50, grey = 100 }, D.bands)
		assert.is_false(D.bandsConfirmed)
	end)

	it("has the five skills, each with a name and a kind", function()
		local kinds = { [633] = "lock", [186] = "node", [182] = "node", [393] = "skin", [356] = "fish" }
		for _, id in ipairs(SKILLS) do
			local s = D.skills[id]
			assert.is_table(s, "skill " .. id)
			assert.is_string(s.name)
			assert.equal(kinds[id], s.kind)
		end
		assert.equal(5, D.skills[633].capPerLevel)
		assert.equal(16, D.skills[633].learnLevel)
		assert.is_false(D.skills[393].formulaConfirmed)
		assert.is_false(D.skills[356].baseConfirmed)
	end)

	it("gives every map it names a size in yards", function()
		for id, m in pairs(D.maps) do
			assert.is_number(id)
			assert.is_string(m.name)
			assert.is_true(m.w > 0 and m.h > 0, m.name)
		end
	end)

	it("has targets with a requirement, and something to find them by", function()
		for _, id in ipairs(OUTDOOR) do
			local n = 0
			for key, t in pairs(D.skills[id].targets) do
				n = n + 1
				assert.is_string(key)
				assert.is_number(t.req, key)
				assert.is_true(t.req >= 1, key)
				assert.is_true(t.objects ~= nil or t.item ~= nil or t.npc ~= nil or t.new == true, key)
				if not t.new then
					assert.is_string(t.name, key)
				end
			end
			assert.is_true(n > 0, "skill " .. id)
		end
	end)

	it("has unique spot ids and sane fields on every spot", function()
		local seen = {}
		eachSpot(function(spot, skill)
			assert.is_string(spot.id)
			assert.is_nil(seen[spot.id], spot.id)
			seen[spot.id] = true
			assert.is_true(spot.req <= spot.top, spot.id)
			assert.is_true(#spot.gets > 0, spot.id)
			for _, g in ipairs(spot.gets) do
				assert.is_table(skill.targets[g.t], spot.id .. " gets " .. tostring(g.t))
				assert.is_true(g.n >= 1, spot.id)
			end
			if spot.map then
				assert.is_table(D.maps[spot.map], spot.id)
				assert.is_string(spot.zone)
				assert.is_true(percent(spot.x) and percent(spot.y), spot.id)
			else
				assert.is_string(spot.instance, spot.id)
			end
			if spot.instance then
				assert.is_nil(spot.pts, spot.id)
			elseif not spot.manual then
				assert.is_true(percent(spot.r), spot.id)
				assert.is_true(spot.classic, spot.id)
			end
			for _, k in ipairs({ "area", "note" }) do
				assert.is_true(spot[k] == nil or type(spot[k]) == "string", spot.id)
			end
		end)
	end)

	it("has flight points on a known map, never a negative distance", function()
		eachSpot(function(spot)
			for side, fp in pairs(spot.fp or {}) do
				assert.is_true(side == "A" or side == "H", spot.id)
				assert.is_string(fp.name)
				assert.is_table(D.maps[fp.map], spot.id)
				assert.is_true(percent(fp.x) and percent(fp.y), spot.id)
				assert.is_true(fp.yd >= 0, spot.id)
			end
		end)
	end)

	it("lists mobs with a level range inside the spot's range", function()
		eachSpot(function(spot)
			local m = spot.mobs
			if m then
				assert.is_true(m.min <= m.max, spot.id)
				assert.is_true(#m.list >= 1 and #m.list <= 4, spot.id)
				for _, mob in ipairs(m.list) do
					assert.is_number(mob[1])
					assert.is_string(mob[2])
					assert.is_true(m.min <= mob[3] and mob[3] <= mob[4] and mob[4] <= m.max, spot.id)
				end
			end
		end)
	end)

	describe("routes", function()
		it("visit every point once, with a target and a start per point", function()
			eachSpot(function(spot, _, skillID)
				if spot.pts then
					assert.equal(0, #spot.pts % 2, spot.id)
					local n = #spot.pts / 2
					local seen = {}
					for i = 1, n do
						local x, y = spot.pts[2 * i - 1], spot.pts[2 * i]
						assert.is_true(percent(x) and percent(y), spot.id)
						-- lock boxes can share a map position on different floors: z tells them apart
						local key = ("%.2f:%.2f:%s"):format(x, y, spot.z and spot.z[i] or "")
						assert.is_nil(seen[key], spot.id .. " visits " .. key .. " twice")
						seen[key] = true
					end
					assert.equal(n, #spot.pk, spot.id)
					for _, k in ipairs(spot.pk) do
						assert.is_true(k >= 0 and k <= #spot.gets, spot.id)
					end
					if skillID == 633 then
						assert.equal(spot.sites, n, spot.id .. ": a lock spot keeps every position")
						assert.equal(n, #spot.z, spot.id)
					elseif spot.sampled then
						assert.equal(LOOP_CAP, n, spot.id)
						assert.is_true(spot.sites > n, spot.id)
					else
						assert.equal(spot.sites, n, spot.id)
						assert.is_true(n <= LOOP_CAP, spot.id)
					end
					for _, k in ipairs({ "startA", "startH" }) do
						assert.is_true(spot[k] == nil or (spot[k] >= 1 and spot[k] <= n), spot.id)
					end
				end
			end)
		end)

		it("have a length that is the sum of their legs", function()
			eachSpot(function(spot)
				if spot.pts then
					local n = #spot.pts / 2
					-- the points are rounded to 0.01 map percent: up to about a yard and a half per leg
					assert.is_true(math.abs(legs(spot) - spot.loopYd) <= 2 * n + 2, spot.id)
				end
			end)
		end)

		it("are never longer after 2-opt than the nearest-neighbour tour they started from", function()
			local shorter = 0
			eachSpot(function(spot)
				if spot.pts then
					assert.is_true(spot.loopYd <= spot.nnYd, spot.id)
					if spot.loopYd < spot.nnYd then
						shorter = shorter + 1
					end
				end
			end)
			assert.is_true(shorter > 0)
		end)

		it("start at the first point for the Alliance when both sides have a flight point", function()
			eachSpot(function(spot)
				if spot.pts and spot.startA then
					assert.equal(1, spot.startA, spot.id)
				end
			end)
		end)
	end)

	describe("known places", function()
		it("puts the Alther's Mill practice lockboxes in Redridge Mountains near 47, 45", function()
			local spot = find(633, 1433, 47, 45, 1.5)
			assert.is_table(spot)
			assert.equal("Redridge Mountains", spot.zone)
			assert.equal("Alther's Mill", spot.area)
			assert.equal(1, spot.req)
			assert.equal("practice-lockbox-1", spot.gets[1].t)
		end)

		it("puts the Angor Fortress footlockers in Badlands near 42, 28, two tiers on one loop", function()
			local spot = find(633, 1418, 42, 28, 1.5)
			assert.is_table(spot)
			assert.equal("Badlands", spot.zone)
			assert.equal(150, spot.req)
			assert.equal(175, spot.top)
			assert.equal(2, #spot.gets)
		end)

		it("puts the Buccaneer's Strongboxes on the ship in The Barrens near 65, 45", function()
			local spot = find(633, 1413, 65, 45, 1.5)
			assert.is_table(spot)
			assert.equal("The Barrens", spot.zone)
			assert.equal("buccaneers-strongbox-1", spot.gets[1].t)
		end)

		it("puts the Scarlet Monastery doors in Tirisfal Glades, not Western Plaguelands", function()
			assert.is_table(find(633, 1420, 85, 31, 2))
		end)

		it("knows who starts the lockpicking quests", function()
			local q = D.skills[633].quests
			assert.equal(2281, q.A.quest)
			assert.equal(2382, q.H.quest)
			assert.is_true(percent(q.A.x) and percent(q.H.y))
		end)
	end)

	it("lists the Forever-only nodes as targets without a position", function()
		for _, id in ipairs({ 186, 182 }) do
			local n = 0
			for _, t in pairs(D.skills[id].targets) do
				if t.new then
					n = n + 1
					assert.is_number(t.lock)
				end
			end
			assert.is_true(n > 0, "skill " .. id)
		end
	end)

	it("has a base skill per fishing zone", function()
		local zones = D.skills[356].zones
		assert.is_true(#zones > 20)
		for _, z in ipairs(zones) do
			assert.is_string(z.zone)
			assert.is_number(z.base)
			assert.is_true(z.map == nil or type(z.map) == "number")
		end
	end)
end)

describe("Data/Trainers.lua", function()
	local T = load("Data/Trainers.lua")
	local ROLES = { trainer = true, recipes = true, recipedrop = true }

	it("says where it comes from", function()
		assert.equal(1, T.trainersMeta.version)
		assert.truthy(T.trainersMeta.classicSource:find("unconfirmed for Forever", 1, true))
	end)

	it("has one sane row per NPC", function()
		local seen = {}
		assert.is_true(#T.trainers > 300)
		for _, r in ipairs(T.trainers) do
			assert.is_number(r.id)
			assert.is_nil(seen[r.id], r.id)
			seen[r.id] = true
			assert.is_string(r.name)
			assert.is_true(ROLES[r.role], r.name)
			assert.is_true(r.faction == nil or r.faction == "A" or r.faction == "H" or r.faction == "B", r.name)
			assert.is_nil(r.teachesTo)
			if r.nopos then
				assert.is_nil(r.x, r.name)
				assert.is_nil(r.classic, r.name)
			else
				assert.is_number(r.map, r.name)
				assert.is_true(percent(r.x) and percent(r.y), r.name)
				assert.is_string(r.place, r.name)
				-- exactly one source for the position: Classic, wow-professions.com (site) or seen in game
				local n = (r.classic and 1 or 0) + (r.site and 1 or 0) + (r.seen and 1 or 0)
				assert.equal(1, n, r.name)
			end
		end
	end)

	it("gives trainers the profession name the guide reads and the skill line", function()
		for _, r in ipairs(T.trainers) do
			if r.role == "trainer" then
				assert.is_string(r.trains, r.name)
				local skills = type(r.skill) == "table" and r.skill or { r.skill }
				assert.is_true(#skills >= 1, r.name)
				for _, s in ipairs(skills) do
					assert.is_number(s, r.name)
				end
			end
		end
	end)

	it("lists recipes as item ids, limited stock only for recipes it lists", function()
		for _, r in ipairs(T.trainers) do
			if r.role ~= "trainer" then
				assert.is_true(#r.recipes >= 1, r.name)
			end
			local has = {}
			for _, item in ipairs(r.recipes or {}) do
				assert.is_number(item, r.name)
				has[item] = true
			end
			for item, n in pairs(r.limited or {}) do
				assert.is_true(has[item], r.name)
				assert.is_true(n >= 1, r.name)
			end
			if r.role == "recipedrop" then
				assert.is_nil(r.sells, r.name)
			end
		end
	end)
end)
